{
  "artifact": {
    "path": "union-acceptance/supplier-code-review-capability.test.mjs",
    "text": "import test from "node:test";
import assert from "node:assert/strict";
import { DEFAULT_FORAGER_POLICY, bidForBoardOffer, missionForAward, deliveryFromResult } from "../src/improvement-board-forager.mjs";

test("supplier-code-review-capability", () => {
  const lot = { id: "urn:lot:0", type: "SoftwareDevelopmentWorkLot", consumer: "urn:c", requestedChanges: ["fix"], boardTerms: { requiredCapabilities: ["software-engineering", "code-review"], territory: "/c", taskClass: "fix" }, productContract: { validationChecks: [], prohibitedFields: ["mutation"] }, ownedTargetRoots: ["/"], acceptanceCommands: [{ runner: "node", argv: ["test.mjs"] }] };
  const quote = { id: "q", type: "ImprovementBuyerQuote", lot: lot.id, consideration: { amount: 10, unit: "relative-resolution-milliquanta-v1" } };
  const offer = { "@context": "https://www.w3.org/ns/activitystreams", type: "Offer", object: lot, attachment: [quote] };
  const capacity = { capacityEpochSnapshot: { id: "e", supplier: "urn:ame:free-compute-dev" }, capacityReservationSnapshot: { id: "r", supplier: "urn:ame:free-compute-dev", board: "urn:c", activity: "o", lot: lot.id, quote: quote.id, resourceClass: "c", validThroughTick: 1, availableLotsAtReservation: 1 }, capacityEpoch: "e", capacityReservation: "r", capacityValidThroughTick: 1, capacityResourceClass: "c", availableLotsAtReservation: 1, maximumConcurrentLots: 1 };
  assert.ok(DEFAULT_FORAGER_POLICY.capabilities.includes("code-review"), "The default supplier policy explicitly includes code-review.");
  const bid = bidForBoardOffer(offer, DEFAULT_FORAGER_POLICY, capacity);
  assert.ok(bid !== null, "The exact code-review-bearing lot qualifies through the normal capacity-bound bid route.");
  const award = { id: "a", type: "Accept", target: "urn:ame:free-compute-dev", object: { type: "ImprovementProposalAward", lot: lot.id, bid: bid.id, customerMutationAuthorized: false } };
  const mission = missionForAward(award, bid);
  assert.equal(mission.apply, false, "Mission must not apply changes.");
  assert.equal(mission.semanticReview, true, "The resulting mission remains proposal-only with semanticReview true.");
  const result = { id: "t", executionProvider: "urn:ame:software-mission-execution-service", executionReceipt: { inputNi: "ni", outputNi: "no" }, outcome: { verified: true, proposal: { proposalOnly: true, customerMutation: false, changes: [{ path: "/" }], authorProviders: ["urn:author"] }, semanticReview: { reviews: [] } } };
  assert.throws(() => deliveryFromResult(award, bid, result), /review-residue/, "Delivery refuses a candidate lacking a distinct reviewer.");
});"
  },
  "rationale": "The test verifies that the forager includes 'code-review' in its capabilities, qualifies lots with that requirement, structures missions with semanticReview enabled, and strictly validates that delivery fails if an independent, review is missing, ensuring the code-review capability is enforced as per requirements."
}
